const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3002', { waitUntil: 'networkidle' });
  await page.locator('#begin-button').click();
  await page.locator('#help-button').click();
  const helpVisible = await page.locator('#help-modal').evaluate(el => !el.classList.contains('hidden'));
  await page.locator('[data-close="help-modal"]').last().click();
  await page.locator('.tool[data-tool="orb"]').click();
  await page.locator('#world').click({ position: { x: 640, y: 380 } });
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('muse-no-edges-v1')));
  await page.keyboard.down('d'); await page.waitForTimeout(500); await page.keyboard.up('d');
  const coords = await page.locator('#coordinates').textContent();
  await page.reload({ waitUntil: 'networkidle' });
  const persisted = await page.evaluate(() => JSON.parse(localStorage.getItem('muse-no-edges-v1'))?.creations?.length);
  console.log(JSON.stringify({helpVisible, created: saved.creations.length, movementCoords: coords, persisted, errors}, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
